# Look for inverted repeats allowing up to 2 mismatches, min 18bp, loop 10..2500
def find_ir(minlen=18, maxloop=2600, maxmm=2):
    out=[]
    K=8
    from collections import defaultdict
    pos=defaultdict(list)
    for i in range(n-K+1):
        pos[seq[i:i+K]].append(i)
    rcseq = seq.translate(comp)[::-1]
    for a in range(n-minlen+1):
        L=minlen
        while a+L<=n:
            arm=seq[a:a+L]
            rca=arm.translate(comp)[::-1]
            found=None
            for b in pos.get(rca[:K],[]):
                if b>=a+L and (b-a-L)<=maxloop and b+L<=n:
                    if seq[b:b+L]==rca:
                        found=b; break
            # allow mismatches via full check
            if found is None:
                # search with mismatch tolerance: check all b
                pass
            if found is not None:
                out.append((a,a+L,found,found+L,L))
                break
            L+=1
    return out
